def is_simple_power(x, n):
    """
    Return True if x is a simple power of n, i.e. x == n**k for some
    non-negative integer k, and False otherwise.
    """
    if n == 1:
        return x == 1
    if n == -1:
        return x in (1, -1)
    if n == 0:
        return x in (0, 1)

    if x == 1:
        return True
    if x == 0:
        return False

    target = abs(x)
    value = 1

    if abs(n) > 1:
        while abs(value) < target:
            value *= n
    else:
        while abs(value) > target:
            value *= n

    return value == x
